function build_market_deck(): array {
    $deck = [];
    $market_cards = [
        'sword_cane' => 3,
        'bazooka' => 2,
        'ram' => 3,
        'holo_projector' => 2,
        'drone' => 3,
        'fake_passports' => 3,
        'motorbike' => 3,
        'limousine' => 3,
        'attack_helicopter' => 2,
        'doorkicker' => 6,
        'reputable_driver' => 6,
        'speedboat_mechanic' => 4,
        'scuba_infiltrator' => 4,
        'hoodied_hacker' => 4,
        'savvy_saboteur' => 4,
        'codename_jack' => 1,
        'the_chameleon' => 1,
        'burn_notice' => 6,
        'paperwork' => 4,
        'para_drop' => 6,
        'multitasking' => 4,
        'training_procedure' => 4,
        'off_shore_investment' => 10,
        'orbital_investment' => 8,
    ];
    foreach ($market_cards as $id => $count) {
        for ($i = 0; $i < $count; $i++) {
            $deck[] = $id;
        }
    }
    shuffle($deck);
    return $deck;
}

function build_mission_decks(): array {
    $missions = [
        1 => [
            'narrow_getaway' => 4,
            'arm_wrestling' => 4,
            'convent_secrets' => 4,
            'gate_hacking' => 4,
        ],
        2 => [
            'train_hijinx' => 4,
            'fencing_duel' => 4,
            'traveling_troupe' => 4,
            'retinal_scan' => 4,
        ],
        3 => [
            'halo_drop' => 2,
            'rooftop_showdown' => 2,
            'megastar_machinations' => 2,
            'embassy_safe' => 2,
        ],
    ];
    $decks = [];
    foreach ($missions as $tier => $cards) {
        $deck = [];
        foreach ($cards as $id => $count) {
            for ($i = 0; $i < $count; $i++) {
                $deck[] = $id;
            }
        }
        shuffle($deck);
        $decks[$tier] = $deck;
    }
    return $decks;
}

